<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {init,use} from 'echarts/core'
import {LineChart,ScatterChart} from 'echarts/charts'
import {GridComponent,TooltipComponent,LegendComponent,DataZoomComponent,MarkAreaComponent,MarkLineComponent,MarkPointComponent,AriaComponent} from 'echarts/components'
import {CanvasRenderer} from 'echarts/renderers'
import type {EChartsType} from 'echarts/core'
import type {Anomaly,Context,Metric,Sample} from '../domain'
import {metricInfo} from '../domain'
import {samplesFor} from '../services/demo'
use([LineChart,ScatterChart,GridComponent,TooltipComponent,LegendComponent,DataZoomComponent,MarkAreaComponent,MarkLineComponent,MarkPointComponent,AriaComponent,CanvasRenderer])
const props=withDefaults(defineProps<{context:Context;samples?:Sample[];metrics?:Metric[];start?:string;end?:string;anomalies?:Anomaly[];focusId?:string;scatter?:boolean;compact?:boolean}>(),{metrics:()=>['supply','return','pressure','flow'],start:'2026-11-03T00:00',end:'2026-11-03T08:00',anomalies:()=>[]})
const emit=defineEmits<{select:[id:string]}>();const element=ref<HTMLDivElement>();let chart:EChartsType|undefined;let observer:ResizeObserver|undefined
const narrow=ref(false),narrowMetric=ref<Metric>('supply')
const data=computed(()=>props.samples??samplesFor(props.context,props.start,props.end))
function render(target=chart,full=false){if(!target)return;const focus=props.anomalies.find(a=>a.id===props.focusId);const available=props.metrics.filter(m=>props.context.segment.metrics.includes(m)),metrics=narrow.value&&!full?[available.includes(narrowMetric.value)?narrowMetric.value:available[0]!].filter(Boolean):available,units=[...new Set(metrics.map(m=>metricInfo[m].unit))]

if(available.length&&!available.includes(narrowMetric.value))narrowMetric.value=available[0]!
if(!data.value.length||!metrics.length){target.clear();return}
const series=metrics.map((m,i)=>({name:`${metricInfo[m].label} (${metricInfo[m].unit})`,type:'line',smooth:.28,showSymbol:false,yAxisIndex:units.indexOf(metricInfo[m].unit),data:data.value.filter(s=>s.metric===m).map(s=>[new Date(s.time).getTime(),s.value]),lineStyle:{width:2,color:metricInfo[m].color,type:m==='pressure'?'dashed':'solid'},itemStyle:{color:metricInfo[m].color},areaStyle:m==='supply'?{opacity:.06}:undefined,markPoint:{symbol:'circle',symbolSize:9,itemStyle:{color:'#dc2626',borderColor:'#f8fafc',borderWidth:2},label:{show:false},data:props.anomalies.filter(a=>a.metric===m).map(a=>({name:a.title,coord:[Math.max(new Date(props.start).getTime(),new Date(a.start).getTime()),a.value]}))},markArea:i===0?{itemStyle:{color:'rgba(239,68,68,.12)',borderColor:'#ef4444',borderWidth:1,borderType:'dashed'},label:{color:'#b91c1c',fontSize:10},data:props.anomalies.map(a=>[{name:a.title,xAxis:new Date(a.start).getTime()},{xAxis:a.end?new Date(a.end).getTime():new Date(props.end).getTime()}])}:undefined}))
target.setOption(props.scatter?{animation:false,textStyle:{fontFamily:'-apple-system, BlinkMacSystemFont, Segoe UI, Microsoft YaHei, sans-serif'},grid:{left:65,right:30,top:45,bottom:65},tooltip:{trigger:'item',backgroundColor:'#ffffff',borderColor:'#e2e8f0',textStyle:{color:'#1e293b'}},xAxis:{name:'流量偏移 (m³/h)',nameLocation:'middle',nameGap:35,type:'value',axisLabel:{color:'#64748b'},splitLine:{lineStyle:{color:'#e2e8f0'}}},yAxis:{name:'温度变化 (℃)',type:'value',axisLabel:{color:'#64748b'},splitLine:{lineStyle:{color:'#e2e8f0'}}},series:[{type:'scatter',symbolSize:12,itemStyle:{color:'#ef4444'},data:Array.from({length:20},(_,i)=>[i*.8,Number((-i*.23+Math.sin(i)*.18).toFixed(2))])},{type:'line',showSymbol:false,lineStyle:{color:'#2563eb'},data:[[0,0],[16,-4.6]]}]}:{animation:false,aria:{enabled:true},textStyle:{fontFamily:'-apple-system, BlinkMacSystemFont, Segoe UI, Microsoft YaHei, sans-serif'},legend:{top:5,textStyle:{color:'#475569',fontSize:11},itemWidth:15,itemHeight:2},grid:{left:55,right:units.length>2?115:65,top:60,bottom:props.compact?50:80},tooltip:{trigger:'axis',backgroundColor:'#f8fafc',borderColor:'#2563eb',textStyle:{color:'#1e293b',fontSize:12}},xAxis:{type:'time',splitNumber:target.getWidth()<480?3:8,min:new Date(props.start).getTime(),max:new Date(props.end).getTime(),axisLabel:{hideOverlap:true,color:'#64748b',formatter:(v:number)=>new Date(v).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})},axisLine:{lineStyle:{color:'#cbd5e1'}},splitLine:{show:true,lineStyle:{color:'#e2e8f0'}}},yAxis:units.map((u,i)=>({type:'value',name:u,scale:true,position:i===0?'left':'right',offset:i>1?(i-1)*60:0,nameTextStyle:{color:'#64748b'},axisLabel:{color:'#64748b',fontSize:10},splitLine:{show:i===0,lineStyle:{color:'#e2e8f0'}}})),dataZoom:props.compact?[]:[{type:'inside',startValue:focus?new Date(focus.start).getTime()-1200000:undefined,endValue:focus?new Date(focus.end??props.end).getTime()+1200000:undefined},{type:'slider',bottom:8,height:20,borderColor:'#cbd5e1',fillerColor:'rgba(37,99,235,.12)',handleStyle:{color:'#2563eb'},textStyle:{color:'#64748b'}}],series},true)}
onMounted(()=>{if(!element.value)return;narrow.value=element.value.clientWidth<480;chart=init(element.value);render();chart.on('click',p=>{const t=Array.isArray(p.value)?Number(p.value[0]):NaN;const a=props.anomalies.find(a=>a.title===p.name||t>=new Date(a.start).getTime()&&t<=new Date(a.end??props.end).getTime());if(a)emit('select',a.id)});observer=new ResizeObserver(()=>{const next=!!element.value&&element.value.clientWidth<480;if(next!==narrow.value){narrow.value=next;render()}chart?.resize()});observer.observe(element.value)})
watch(()=>[props.context,props.samples,props.metrics,props.start,props.end,props.anomalies,props.focusId,props.scatter],()=>{const focus=props.anomalies.find(a=>a.id===props.focusId);if(focus&&narrow.value&&props.metrics.includes(focus.metric))narrowMetric.value=focus.metric;render();chart?.resize()},{deep:true,flush:'post'});onBeforeUnmount(()=>{observer?.disconnect();chart?.dispose()});defineExpose({image:()=>{const host=document.createElement('div');host.style.cssText='position:fixed;left:-10000px;top:0;width:1400px;height:600px';document.body.appendChild(host);const output=init(host);try{render(output,true);return output.getDataURL({type:'png',pixelRatio:1.5,backgroundColor:'#f8fafc'})}finally{output.dispose();host.remove()}},reset:()=>chart?.dispatchAction({type:'dataZoom',start:0,end:100})})
</script>
<template><label v-if="narrow&&!scatter&&metrics.length>1&&data.length" class="chart-mobile-parameter">图表参数<select v-model="narrowMetric" aria-label="图表监测参数" @change="render()"><option v-for="m in metrics" :key="m" :value="m">{{metricInfo[m].label}}（{{metricInfo[m].unit}}）</option></select></label><div v-show="data.length" ref="element" :class="['telemetry-chart',{compact}]" role="img" aria-label="运行参数时序曲线，支持悬浮查看、图例切换与区间缩放" :data-focused-event="focusId||undefined" data-testid="telemetry-chart"></div><div v-if="!data.length" class="empty">当前管段或时间范围暂无数据，请调整选择。</div></template>
